// Clasa a VIII-a, manual Litera A1954 (OM 4500/10.07.2025).
// Aici: testul inițial, Unitățile 1–2, Unitatea 3 până la capăt
// și începutul Unității 4, până la opinie și preferințe.
// Filtrul este analiza probei de Evaluare Națională (OM 4730/18.08.2022),
// pe lucrările 2023–2026: ce aduce puncte stă în plan principal;
// ce nu a fost item rămâne plan secundar, scurt, fără exercițiu de examen.
// Nu copiem fragmente. Scena este scrisă în lecție.
// Foaia cu puncte și fișa de observare nu sunt lecții.

function lesson(id, title, block) {
  const example = String(block.example || '').replace(/^Exemplu lucrat:\s*/i, '');
  const platter = [block.theory, `Exemplu lucrat: ${example}`, block.tryThis, block.recap].join('\n\n');
  return {
    id,
    title,
    platter,
    theory: block.theory,
    example,
    tryThis: block.tryThis,
    recap: block.recap
  };
}

